void Solver::restart() {
    // Reset LBD statistics more aggressively
    fast_lbd_sum = 0;
    slow_lbd_sum = 0;
    lbd_queue_size = 0;
    lbd_queue_pos = 0;

    // Backtrack to root level
    backtrack(0);

    // Rephase variables with a mixed strategy
    for (int i = 1; i <= vars; ++i) {
        int r = rand() % 100;
        if (r < 50) {
            // Use the best phase observed so far
            saved[i] = local_best[i];
        } else if (r < 75) {
            // Use the opposite of the best phase
            saved[i] = -local_best[i];
        } else {
            // Random phase
            saved[i] = (rand() & 1) ? 1 : -1;
        }
    }
}
